// Font lookup and text measurement for the caption engine.
//
// The engine lays out every caption word itself and pins it with \pos, so it
// has to measure text with the SAME font file libass will draw with. Both read
// public/fonts via font-manifest.json (generated by scripts/sync-caption-fonts.mjs),
// and libass is pointed at that folder with `fontsdir`. Faces are referenced
// by their exact full name, which libass matches directly, so a weight is never
// synthesised from a neighbouring face.

import fs from "node:fs";
import path from "node:path";
import * as fontkit from "fontkit";
import manifest from "./font-manifest.json";

export interface FontFace {
  family: string;
  weight: number;
  italic: boolean;
  file: string;
  fullName: string;
  devanagari: boolean;
}

const FACES = manifest as FontFace[];

export const CAPTION_FONTS_DIR = path.join(process.cwd(), "public", "fonts");

/** The face used for Devanagari words in a template whose font has no Devanagari glyphs. */
export const DEVANAGARI_FALLBACK = { family: "Mukta", weight: 800, italic: false };

/**
 * Closest bundled face: same family and style, nearest weight; then the other
 * style; never another family (a wrong family is a design bug, so it throws).
 */
export function resolveFace(family: string, weight: number, italic = false): FontFace {
  const faces = FACES.filter((f) => f.family === family);
  if (!faces.length) throw new Error(`Caption font "${family}" is not bundled; add it to scripts/sync-caption-fonts.mjs`);
  const sameStyle = faces.filter((f) => f.italic === italic);
  const pool = sameStyle.length ? sameStyle : faces;
  return pool.reduce((best, f) => (Math.abs(f.weight - weight) < Math.abs(best.weight - weight) ? f : best));
}

export function hasFace(family: string): boolean {
  return FACES.some((f) => f.family === family);
}

interface LoadedFont {
  font: fontkit.Font;
  /** Pixels per font unit at a 1px em. */
  unitsPerEm: number;
  /** VSFilter/libass cell height (winAscent + winDescent) in font units. */
  cellUnits: number;
  ascentUnits: number;
}

const loaded = new Map<string, LoadedFont>();

function load(face: FontFace): LoadedFont {
  const hit = loaded.get(face.file);
  if (hit) return hit;
  const buf = fs.readFileSync(/*turbopackIgnore: true*/ path.join(CAPTION_FONTS_DIR, face.file));
  const font = fontkit.create(buf) as fontkit.Font;
  const os2 = (font as unknown as { "OS/2"?: { winAscent?: number; winDescent?: number } })["OS/2"];
  const winA = os2?.winAscent ?? font.ascent;
  const winD = os2?.winDescent ?? Math.abs(font.descent);
  const entry: LoadedFont = { font, unitsPerEm: font.unitsPerEm, cellUnits: winA + winD, ascentUnits: winA };
  loaded.set(face.file, entry);
  return entry;
}

/** Width in px of `text` set at an em size of `emPx`, plus per-character tracking. */
export function measureText(face: FontFace, text: string, emPx: number, trackingEm = 0): number {
  const { font, unitsPerEm } = load(face);
  const run = font.layout(text);
  const advance = run.positions.reduce((sum, p) => sum + p.xAdvance, 0);
  const chars = Array.from(text).length;
  return (advance / unitsPerEm) * emPx + trackingEm * emPx * chars;
}

/**
 * The ASS \fs value that renders this face at an em size of `emPx`. libass
 * (like VSFilter) treats \fs as the cell height winAscent + winDescent, not
 * the em, so the same \fs gives different em sizes in different fonts.
 */
export function assFontSize(face: FontFace, emPx: number): number {
  const { unitsPerEm, cellUnits } = load(face);
  return emPx * (cellUnits / unitsPerEm);
}

export function hasGlyphs(face: FontFace, text: string): boolean {
  const { font } = load(face);
  for (const ch of text) {
    const cp = ch.codePointAt(0)!;
    if (cp < 0x80 || /\p{M}/u.test(ch)) continue;
    if (!font.hasGlyphForCodePoint(cp)) return false;
  }
  return true;
}

export const DEVANAGARI_RE = /[ऀ-ॿ]/;
